/// Custom dual-cubemap blended skybox render pipeline.
pub mod skybox {
    use bevy::camera::Exposure;
    use bevy::core_pipeline::core_3d::CORE_3D_DEPTH_FORMAT;
    use bevy::core_pipeline::skybox::{SkyboxBindGroup, SkyboxPipelineId};
    use bevy::prelude::*;
    use bevy::render::extract_component::{ComponentUniforms, DynamicUniformIndex, UniformComponentPlugin};
    use bevy::render::render_asset::RenderAssets;
    use bevy::render::render_resource::binding_types::{sampler, texture_cube, uniform_buffer};
    use bevy::render::render_resource::*;
    use bevy::render::renderer::RenderDevice;
    use bevy::render::sync_component::{SyncComponent, SyncComponentPlugin};
    use bevy::render::sync_world::RenderEntity;
    use bevy::render::texture::GpuImage;
    use bevy::render::view::{ExtractedView, Msaa, ViewUniform, ViewUniforms};
    use bevy::render::{Extract, ExtractSchedule, GpuResourceAppExt, Render, RenderApp, RenderStartup, RenderSystems};
    use bevy::shader::Shader;

    /// Embedded WESL source for the blended skybox pipeline.
    pub use super::BLENDED_SKYBOX_WESL;

    /// Camera component driving the dual-cubemap blended skybox shader.
    #[derive(Component, Clone, Debug, Default, PartialEq)]
    pub struct BlendedSkybox {
        pub cubemap_a: Option<Handle<Image>>,
        pub cubemap_b: Option<Handle<Image>>,
        pub brightness_a: f32,
        pub brightness_b: f32,
        pub rotation_a: Quat,
        pub rotation_b: Quat,
        pub color_a: Vec4,
        pub color_b: Vec4,
        pub blend: f32,
        pub alpha: f32,
    }

    /// GPU uniform buffer for [`BlendedSkybox`].
    #[derive(Component, ShaderType, Clone, Copy, Debug)]
    pub struct BlendedSkyboxUniforms {
        pub transform_a: Mat4,
        pub transform_b: Mat4,
        pub color_a: Vec4,
        pub color_b: Vec4,
        pub brightness_a: f32,
        pub brightness_b: f32,
        pub blend: f32,
        pub alpha: f32,
        pub has_a: u32,
        pub has_b: u32,
        pub _pad0: u32,
        pub _pad1: u32,
    }

    #[derive(Resource, Clone)]
    struct BlendedSkyboxShader(Handle<Shader>);

    /// Plugin registering the blended skybox shader and render pipeline.
    #[derive(Default)]
    pub struct BlendedSkyboxPlugin;

    impl Plugin for BlendedSkyboxPlugin {
        fn build(&self, app: &mut App) {
            if !app.world().contains_resource::<Assets<Shader>>() {
                return;
            }
            let shader = app
                .world_mut()
                .resource_mut::<Assets<Shader>>()
                .add(Shader::from_wesl(
                    BLENDED_SKYBOX_WESL,
                    "embedded://quillshade/light/blended_skybox.wesl",
                ));
            app.insert_resource(BlendedSkyboxShader(shader.clone()));

            if app.get_sub_app_mut(RenderApp).is_none() {
                return;
            }
            app.add_plugins((
                SyncComponentPlugin::<BlendedSkybox, Self>::default(),
                UniformComponentPlugin::<BlendedSkyboxUniforms>::default(),
            ));

            let Some(render_app) = app.get_sub_app_mut(RenderApp) else {
                return;
            };
            render_app
                .insert_resource(BlendedSkyboxShader(shader))
                .init_gpu_resource::<SpecializedRenderPipelines<BlendedSkyboxPipeline>>()
                .add_systems(ExtractSchedule, extract_blended_skybox)
                .add_systems(RenderStartup, init_blended_skybox_pipeline)
                .add_systems(
                    Render,
                    (
                        prepare_blended_skybox_pipelines.in_set(RenderSystems::Prepare),
                        prepare_blended_skybox_bind_groups.in_set(RenderSystems::PrepareBindGroups),
                    ),
                );
        }
    }

    impl SyncComponent<RenderApp, BlendedSkyboxPlugin> for BlendedSkybox {
        type Target = (Self, BlendedSkyboxUniforms, SkyboxPipelineId, SkyboxBindGroup);
    }

    fn extract_blended_skybox(
        mut commands: Commands,
        mut previous_len: Local<usize>,
        query: Extract<Query<(RenderEntity, &BlendedSkybox, Option<&Exposure>)>>,
    ) {
        let mut values = Vec::with_capacity(*previous_len);
        for (entity, skybox, exposure) in &query {
            let exposure = exposure
                .map(Exposure::exposure)
                .unwrap_or_else(|| Exposure::default().exposure());
            let uniforms = BlendedSkyboxUniforms {
                transform_a: Transform::from_rotation(skybox.rotation_a.inverse()).to_matrix(),
                transform_b: Transform::from_rotation(skybox.rotation_b.inverse()).to_matrix(),
                color_a: skybox.color_a,
                color_b: skybox.color_b,
                brightness_a: skybox.brightness_a * exposure,
                brightness_b: skybox.brightness_b * exposure,
                blend: skybox.blend,
                alpha: skybox.alpha,
                has_a: u32::from(skybox.cubemap_a.is_some()),
                has_b: u32::from(skybox.cubemap_b.is_some()),
                _pad0: 0,
                _pad1: 0,
            };
            values.push((entity, (skybox.clone(), uniforms)));
        }
        *previous_len = values.len();
        commands.try_insert_batch(values);
    }

    #[derive(Resource)]
    struct BlendedSkyboxPipeline {
        bind_group_layout: BindGroupLayoutDescriptor,
        shader: Handle<Shader>,
    }

    fn init_blended_skybox_pipeline(mut commands: Commands, shader: Res<BlendedSkyboxShader>) {
        let bind_group_layout = BindGroupLayoutDescriptor::new(
            "blended_skybox_bind_group_layout",
            &BindGroupLayoutEntries::sequential(
                ShaderStages::FRAGMENT,
                (
                    texture_cube(TextureSampleType::Float { filterable: true }),
                    sampler(SamplerBindingType::Filtering),
                    texture_cube(TextureSampleType::Float { filterable: true }),
                    sampler(SamplerBindingType::Filtering),
                    uniform_buffer::<ViewUniform>(true).visibility(ShaderStages::VERTEX_FRAGMENT),
                    uniform_buffer::<BlendedSkyboxUniforms>(true),
                ),
            ),
        );
        commands.insert_resource(BlendedSkyboxPipeline { bind_group_layout, shader: shader.0.clone() });
    }

    #[derive(PartialEq, Eq, Hash, Clone, Copy)]
    struct BlendedSkyboxPipelineKey {
        target_format: TextureFormat,
        samples: u32,
        depth_format: TextureFormat,
    }

    impl SpecializedRenderPipeline for BlendedSkyboxPipeline {
        type Key = BlendedSkyboxPipelineKey;

        fn specialize(&self, key: Self::Key) -> RenderPipelineDescriptor {
            RenderPipelineDescriptor {
                label: Some("blended_skybox_pipeline".into()),
                layout: vec![self.bind_group_layout.clone()],
                vertex: VertexState {
                    shader: self.shader.clone(),
                    entry_point: Some("skybox_vertex".into()),
                    ..default()
                },
                depth_stencil: Some(DepthStencilState {
                    format: key.depth_format,
                    depth_write_enabled: Some(false),
                    depth_compare: Some(CompareFunction::GreaterEqual),
                    stencil: StencilState {
                        front: StencilFaceState::IGNORE,
                        back: StencilFaceState::IGNORE,
                        read_mask: 0,
                        write_mask: 0,
                    },
                    bias: DepthBiasState { constant: 0, slope_scale: 0.0, clamp: 0.0 },
                }),
                multisample: MultisampleState {
                    count: key.samples,
                    mask: !0,
                    alpha_to_coverage_enabled: false,
                },
                fragment: Some(FragmentState {
                    shader: self.shader.clone(),
                    entry_point: Some("skybox_fragment".into()),
                    targets: vec![Some(ColorTargetState {
                        format: key.target_format,
                        blend: Some(BlendState::ALPHA_BLENDING),
                        write_mask: ColorWrites::ALL,
                    })],
                    ..default()
                }),
                ..default()
            }
        }
    }

    fn prepare_blended_skybox_pipelines(
        mut commands: Commands,
        pipeline_cache: Res<PipelineCache>,
        mut pipelines: ResMut<SpecializedRenderPipelines<BlendedSkyboxPipeline>>,
        pipeline: Res<BlendedSkyboxPipeline>,
        cameras: Query<(Entity, &ExtractedView, &Msaa), With<BlendedSkybox>>,
    ) {
        for (entity, view, msaa) in &cameras {
            let pipeline_id = pipelines.specialize(
                &pipeline_cache,
                &pipeline,
                BlendedSkyboxPipelineKey {
                    target_format: view.target_format,
                    samples: msaa.samples(),
                    depth_format: CORE_3D_DEPTH_FORMAT,
                },
            );
            commands.entity(entity).insert(SkyboxPipelineId(pipeline_id));
        }
    }

    #[expect(clippy::too_many_arguments)]
    fn prepare_blended_skybox_bind_groups(
        mut commands: Commands,
        pipeline: Res<BlendedSkyboxPipeline>,
        view_uniforms: Res<ViewUniforms>,
        skybox_uniforms: Res<ComponentUniforms<BlendedSkyboxUniforms>>,
        images: Res<RenderAssets<GpuImage>>,
        render_device: Res<RenderDevice>,
        pipeline_cache: Res<PipelineCache>,
        views: Query<(Entity, &BlendedSkybox, &DynamicUniformIndex<BlendedSkyboxUniforms>)>,
    ) {
        for (entity, skybox, skybox_uniform_index) in &views {
            if skybox.alpha <= 0.0 {
                commands.entity(entity).remove::<SkyboxBindGroup>();
                continue;
            }
            let handle_a = skybox.cubemap_a.as_ref().or(skybox.cubemap_b.as_ref());
            let handle_b = skybox.cubemap_b.as_ref().or(skybox.cubemap_a.as_ref());
            if let (Some(handle_a), Some(handle_b), Some(view_uniforms), Some(skybox_uniforms)) = (
                handle_a,
                handle_b,
                view_uniforms.uniforms.binding(),
                skybox_uniforms.binding(),
            ) && let (Some(image_a), Some(image_b)) = (images.get(handle_a), images.get(handle_b))
                && is_cubemap(image_a)
                && is_cubemap(image_b)
            {
                let bind_group = render_device.create_bind_group(
                    "blended_skybox_bind_group",
                    &pipeline_cache.get_bind_group_layout(&pipeline.bind_group_layout),
                    &BindGroupEntries::sequential((
                        &image_a.texture_view,
                        &image_a.sampler,
                        &image_b.texture_view,
                        &image_b.sampler,
                        view_uniforms,
                        skybox_uniforms,
                    )),
                );
                commands
                    .entity(entity)
                    .insert(SkyboxBindGroup((bind_group, skybox_uniform_index.index())));
            } else {
                commands.entity(entity).remove::<SkyboxBindGroup>();
            }
        }
    }

    fn is_cubemap(image: &GpuImage) -> bool {
        image
            .texture_view_descriptor
            .as_ref()
            .and_then(|desc| desc.dimension)
            == Some(TextureViewDimension::Cube)
    }
}

/// Embedded WESL source for the blended skybox pipeline.
pub const BLENDED_SKYBOX_WESL: &str = "import bevy_render::view::View;\n\nstruct BlendedSkyboxUniforms {\n    transform_a: mat4x4<f32>,\n    transform_b: mat4x4<f32>,\n    color_a: vec4<f32>,\n    color_b: vec4<f32>,\n    brightness_a: f32,\n    brightness_b: f32,\n    blend: f32,\n    alpha: f32,\n    has_a: u32,\n    has_b: u32,\n    _pad0: u32,\n    _pad1: u32,\n}\n\n@group(0) @binding(0) var skybox_a: texture_cube<f32>;\n@group(0) @binding(1) var skybox_a_sampler: sampler;\n@group(0) @binding(2) var skybox_b: texture_cube<f32>;\n@group(0) @binding(3) var skybox_b_sampler: sampler;\n@group(0) @binding(4) var<uniform> view: View;\n@group(0) @binding(5) var<uniform> uniforms: BlendedSkyboxUniforms;\n\nfn coords_to_viewport_uv(position: vec2<f32>, viewport: vec4<f32>) -> vec2<f32> {\n    return (position - viewport.xy) / viewport.zw;\n}\n\nfn coords_to_view_ray_direction(position: vec2<f32>, viewport: vec4<f32>) -> vec3<f32> {\n    let view_position_homogeneous = view.view_from_clip * vec4(\n        coords_to_viewport_uv(position, viewport) * vec2(2.0, -2.0) + vec2(-1.0, 1.0),\n        1.0,\n        1.0,\n    );\n    let view_ray_direction = view_position_homogeneous.xyz / view_position_homogeneous.w;\n    return (view.world_from_view * vec4(view_ray_direction, 0.0)).xyz;\n}\n\nstruct VertexOutput {\n    @builtin(position) position: vec4<f32>,\n}\n\n@vertex\nfn skybox_vertex(@builtin(vertex_index) vertex_index: u32) -> VertexOutput {\n    let clip_position = vec2(\n        f32(vertex_index & 1u),\n        f32((vertex_index >> 1u) & 1u),\n    ) * 4.0 - vec2(1.0);\n    return VertexOutput(vec4(clip_position, 0.0, 1.0));\n}\n\n@fragment\nfn skybox_fragment(in: VertexOutput) -> @location(0) vec4<f32> {\n    let world_ray = coords_to_view_ray_direction(in.position.xy, view.main_pass_viewport);\n    let ray_a = normalize((uniforms.transform_a * vec4(world_ray, 0.0)).xyz);\n    let ray_b = normalize((uniforms.transform_b * vec4(world_ray, 0.0)).xyz);\n\n    // Cube maps are left-handed so we negate the z coordinate.\n    let sample_a = textureSample(skybox_a, skybox_a_sampler, ray_a * vec3(1.0, 1.0, -1.0));\n    let sample_b = textureSample(skybox_b, skybox_b_sampler, ray_b * vec3(1.0, 1.0, -1.0));\n    var sky_a = uniforms.color_a.rgb;\n    if uniforms.has_a != 0u {\n        sky_a = sample_a.rgb * uniforms.brightness_a;\n    }\n    var sky_b = uniforms.color_b.rgb;\n    if uniforms.has_b != 0u {\n        sky_b = sample_b.rgb * uniforms.brightness_b;\n    }\n    let rgb = mix(sky_a, sky_b, uniforms.blend);\n    return vec4(rgb, uniforms.alpha);\n}\n";

