/// Transition curves authored in `quillshade/light/*.curve.ron`, plus built-in [`Curve::Linear`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Default, Serialize, Deserialize)]
pub enum Curve {
    /// Built-in identity linear transition curve (`s = t`).
    #[default]
    Linear,
    /// Curve `smooth` (`quillshade/light/smooth.curve.ron`).
    Smooth,
}

impl Curve {
    /// All available transition curves, starting with [`Curve::Linear`].
    pub const ALL: &'static [Curve] = &[
        Self::Linear,
        Self::Smooth,
    ];

    /// Domain-relative asset path of this curve (`"linear"` for [`Curve::Linear`]).
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Linear => "linear",
            Self::Smooth => "smooth",
        }
    }

    /// Looks up a curve by its domain-relative asset path (`"linear"` returns [`Curve::Linear`]).
    pub fn from_path(path: &str) -> Option<Curve> {
        match path {
            "linear" => Some(Self::Linear),
            "smooth" => Some(Self::Smooth),
            _ => None,
        }
    }

    /// Compiled default [`BakedCurve`] for this curve.
    pub fn default_curve(self) -> BakedCurve {
        match self {
            Self::Linear => BakedCurve::linear(),
            Self::Smooth => BakedCurve { min: 0.0, max: 1.0, points: vec![(0.0, 0.0), (0.25, 0.15), (0.75, 0.85), (1.0, 1.0)] },
        }
    }

    /// Evaluates the compiled curve at `t` in `0.0..=1.0`.
    pub fn sample(self, t: f32) -> f32 {
        match self {
            Self::Linear => t.clamp(0.0, 1.0),
            other => other.default_curve().sample(t),
        }
    }
}

impl bevy::curve::Curve<f32> for Curve {
    fn domain(&self) -> bevy::curve::Interval {
        bevy::curve::Interval::UNIT
    }

    fn sample_unchecked(&self, t: f32) -> f32 {
        (*self).sample(t)
    }
}

/// Bevy [`States`] state machine tracking the active lighting preset or transition.
#[derive(States, Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum State {
    /// Initial state before any lighting preset is applied.
    #[default]
    None,
    /// Active while a transition between two presets is in progress (`0.0 <= t < 1.0`).
    Transitioning,
    /// Settled on environment `day`.
    Day,
    /// Settled on environment `night`.
    Night,
}

#[allow(unreachable_code)]
impl From<Preset> for State {
    fn from(preset: Preset) -> Self {
        preset.state()
    }
}

impl State {
    /// Returns the settled [`Preset`] if this state corresponds to one, or `None` for [`State::None`] and
    /// [`State::Transitioning`].
    pub const fn as_preset(self) -> Option<Preset> {
        match self {
            Self::None | Self::Transitioning => None,
            Self::Day => Some(Preset::Day),
            Self::Night => Some(Preset::Night),
        }
    }
}
